        talk: 'ロシアの地図を見ると、世界一広い国なのに、海の出口がとても少ないことに気づきます。北の白海やバルト海は、冬になると氷で閉ざされてしまいました。船が出せなければ、貿易も海軍も思うようになりません。若き皇帝ピョートル1世は、自分で造船所に入って船づくりを学ぶほど海にこだわった人物です。1696年、黒海に近いアゾフを攻め落としました。ここから、200年以上にわたる南への道が始まります。',
