        talk: '女帝エカチェリーナ2世の時代、ロシアはついに黒海の北岸を手に入れました。クリミア半島には軍港セヴァストーポリがつくられます。でも、地図をもう一度見てください。黒海は袋のような海で、出口はイスタンブルのボスフォラス海峡とダーダネルス海峡だけです。そこを握っているのはオスマン帝国。ロシアがこの海峡を自由に通れるかどうかが、19世紀のヨーロッパ外交の大問題、東方問題の中心になっていきます。',
