    period: '583〜780年', region: 'east', view: 'eastasia', tags: ['tankyu'],
    summary: '律は刑法、令は行政法。隋・唐で整えられた律令は、皇帝が役人を通じて全国の人と土地を直接治めるための設計図だった。日本や新羅も唐の律令を手本に国づくりを行った。',
