        text: '653年、高宗のもとで律の公式注釈である『律疏』がつくられた。のちに『唐律疏議』とよばれ、完全な形で現存する中国最古の法典として、宋・明・清の法やベトナムの法にも大きな影響を与えた。',
        talk: '唐の律は、今でもほぼそのまま読むことができます。653年、律の一つ一つの条文に、くわしい説明をつけた本がつくられたからです。たとえば「人をなぐったら」という条文に、手でなぐった場合、物でなぐった場合、相手が親や上司だった場合など、ていねいな説明がついています。親への罪が特に重いのは、儒学の考えが入っているからです。この本は、のちの中国の王朝やベトナムの法の手本になりました。',
