        talk: '唐の律令にあこがれたのは、まわりの国々でした。日本は遣唐使を送って制度を学び、701年に大宝律令を完成させます。唐の三省六部をまねて二官八省を置き、均田制をまねて班田収授法を始めました。ただし、まるごと写したわけではありません。神々のまつりを担当する神祇官を置くなど、日本に合わせた工夫もしています。「日本」という国号が正式に使われはじめたのも、このころと考えられています。',
        place: '藤原京', lon: 135.81, lat: 34.5, span: 20,
        polities: ['tang', 'japan-pre', 'silla', 'bohai'],
        marks: [{ name: '長安', lon: 108.94, lat: 34.26 }, { name: '金城（新羅の都）', lon: 129.21, lat: 35.84 }]
