        text: '満洲人のホンタイジは内モンゴルのチャハルを服属させ、1636年に国号を大清と改めた。モンゴルの王侯との関係を扱う役所として蒙古衙門を置き、1638年に理藩院と改めた。これがのちの藩部統治の中心機関となる。',
        talk: '清を建てたのは満洲人ですが、もとは人数の少ない民族でした。強い国をつくるには、騎馬の得意なモンゴル人を味方につける必要があります。ホンタイジはモンゴルの有力者と同盟し、結婚によって家族の結びつきも深めました。モンゴルの王侯たちからは、ハーンの位も受けたと伝えられます。そしてモンゴルとの関係を担当する役所をつくりました。これが理藩院です。中国風の六部とは別の、辺境のための特別な役所でした。',
