        talk: '敦煌は、中国から西へ向かう旅人にとって最後の大きな町でした。ここから先は、タクラマカン砂漠をはさんで北の道と南の道に分かれます。前漢の武帝がこの地に郡を置いてから、商人も、兵士も、僧も、みな敦煌で水と食料を整え、旅の安全を祈りました。逆に西から来た人にとっては、ようやく砂漠をこえてたどり着いた中国の入り口です。いろいろな人と文化が集まる場所に、石窟寺院が生まれたのは自然なことでした。',
        place: '敦煌', lon: 94.66, lat: 40.14, span: 12,
