        talk: '1900年のある日、道士の王円籙が窟の掃除をしていると、壁の向こうに空洞があることに気づきました。壁をくずすと、そこには巻物がぎっしりと積み重ねられていたのです。その数は約5万点。11世紀ごろに封じられたと考えられ、漢文だけでなく、チベット語、ウイグル語、ソグド語、さらにはヘブライ語の文書までありました。しかし、その多くはスタインやペリオらに安く買い取られ、ロンドンやパリに運ばれてしまいました。今も文書は世界中に散らばっています。',
