        talk: 'エルサレムは、三つの宗教にとって特別な町です。ユダヤ教の神殿があった町、イエスが十字架にかけられた町、そしてイスラーム教でも大切な聖地です。638年ごろ、アラブのムスリム軍がこの町に入りました。カリフのウマルは、キリスト教徒が教会を使い続けることを認めたと伝えられています。そのウマルが訪れたのが、かつてユダヤ教の神殿が建っていた丘、神殿の丘でした。そこには荒れた地面から大きな岩が顔を出していました。',
