        talk: '岩のドームを建てたのは、ウマイヤ朝のカリフ、アブド=アルマリクです。当時のエルサレムには、キリスト教の立派な聖墳墓教会がそびえていました。カリフは、イスラームの力と信仰を目に見える形で示す建物を求めたと考えられています。八角形の壁の上に、直径約20メートルのドームがのります。内側の壁にはびっしりとモザイクがはられ、コーランの章句がアラビア文字で刻まれました。人の姿は描かず、植物や宝石の模様で飾られています。',
