        talk: 'ドームの中に入ると、まん中に大きな岩がむき出しになっています。イスラーム教の伝えでは、預言者ムハンマドが一夜のうちにメッカからエルサレムへ旅し、この岩から天に昇ったとされます。一方、ユダヤ教では、アブラハムが神の命令で息子をささげようとした場所とも伝えられてきました。一つの岩に、いくつもの物語が重なっているのです。実は岩のドームはモスクではありません。礼拝はすぐ南にあるアクサー=モスクで行われます。',
