        talk: '1099年、ヨーロッパから来た十字軍がエルサレムを攻め落としました。十字軍の人々は、この建物を古いユダヤの神殿だと考え、「主の神殿」とよぶ教会にしてしまいます。ドームの上には金の十字架が立ちました。88年後の1187年、サラディンがエルサレムを取り戻します。サラディンは十字架を下ろし、岩をバラの香水で清めたと伝えられています。このとき、町のキリスト教徒の多くは身代金を払って退去することを許されました。',
