        talk: '今の岩のドームの写真を見ると、外の壁は青や緑のタイルでおおわれています。これは16世紀、オスマン帝国のスレイマン1世が、いたんだモザイクのかわりにはらせたタイルがもとになっています。スレイマン1世はエルサレムの城壁も築き直しました。今、旧市街を囲んでいる城壁は、そのときのものです。ドームの金色の屋根は、20世紀の修理で金をはり直したもので、今では町のどこからでも輝いて見えます。',
