        year: -80, title: 'にぎやかな地方都市',
        text: 'ポンペイはナポリ湾にのぞむ交易の町で、オスク人がつくり、ギリシアやサムニウム人の影響を受けた。前80年、スッラによってローマの植民市とされた。人口は約1万人ほどで、フォルム（広場）、神殿、劇場、浴場、円形闘技場がそろっていた。',
        talk: 'ポンペイは、ナポリ湾に近い、ワインやオリーブ油の取引でにぎわう町でした。人口はおよそ1万人。ローマのような大都会ではありませんが、町の中心には広場フォルムがあり、神殿や公衆浴場、劇場がありました。前70年ごろにつくられた円形闘技場は、今残っている石づくりのものとしては最古級で、約2万人が入れたといわれます。町の北には、緑におおわれた山がそびえていました。それが火山だと、町の人々はほとんど意識していなかったようです。',
