        talk: '噴火の17年前、ポンペイは大きな地震にみまわれました。神殿や家が崩れ、人々は町の建て直しにとりかかります。発掘すると、工事中の建物や、積まれたままの建築資材がたくさん見つかります。今思えば、あの地震は火山が目覚めはじめた合図だったのかもしれません。しかし当時のローマ人は、ヴェスヴィオが火山だという知識をほとんどもっていませんでした。',
