        talk: '昼すぎ、山の上に、松の木のような形の巨大な雲がわき上がりました。これは、湾の向こうから見ていた17歳の小プリニウスの表現です。やがてポンペイには軽石が雨のように降り、屋根が重みで崩れはじめます。逃げおくれた人々を、翌朝、数百度の火砕流がおそいました。小プリニウスの叔父、大プリニウスは艦隊を率いて救助に向かい、その途中で亡くなります。今、火山学ではこの型の噴火を「プリニー式噴火」とよんでいます。',
        place: 'ヴェスヴィオ山', lon: 14.43, lat: 40.82, span: 1,
        polities: ['rome-empire'],
        marks: [{ name: 'ポンペイ', lon: 14.49, lat: 40.75 }, { name: 'ヘルクラネウム', lon: 14.35, lat: 40.81 }, { name: 'ミセヌム', lon: 14.08, lat: 40.78 }]
