        talk: '1700年近く、ポンペイは地中に眠っていました。1748年に本格的な発掘が始まると、人々はおどろきました。かまどにはパンが炭になって残り、壁には「だれそれを役人に選ぼう」という選挙ポスターや、恋人へのラブレターのような落書きが書かれていたのです。19世紀、考古学者フィオレッリは、灰の中にできた空洞に石膏を流しこむ方法を考えました。すると、身をかがめる人や、犬の姿が浮かびあがりました。教科書の中のローマ人が、急に身近な人間として感じられます。',
