        talk: '今、ポンペイには世界中から年に数百万人の観光客が訪れます。でも、掘り出されたことで、壁画や建物は雨や日光にさらされ、少しずつ傷んでいきます。2010年には剣闘士の訓練所が崩れて、大きなニュースになりました。それでも発掘は続いています。町の約3分の1はまだ地下に眠っているともいわれ、近年も色あざやかな壁画や、ファストフード店のようなカウンターが見つかりました。2000年前の町の物語は、今も書き足され続けているのです。',
