        talk: '偉大な指導者が後継者を決めずに亡くなったら、残された人々はどうするでしょう。632年、メディナのムスリムたちはこの問題に直面しました。彼らは話し合って、ムハンマドの古くからの友アブー=バクルを、後継者カリフに選びます。共同体のみんなで決めたのだから正しい、という考え方です。しかし一部の人々は、ムハンマドの血すじにつながるアリーこそふさわしいと考えていました。この意見のちがいが、のちに大きな分かれ目になっていきます。',
