    period: '1341〜1516年', region: 'europe', view: 'europe', tags: ['tankyu'],
    summary: '人文主義（ヒューマニズム）は、ギリシア・ローマの古典を研究し、人間の可能性を重んじた思想である。ペトラルカに始まりイタリアで発展し、エラスムスらによってアルプスの北に広まって、ルネサンスと宗教改革の土台となった。',
