        text: 'イタリアの詩人ペトラルカは、古代ローマの文人キケロらの作品を熱心に集めて研究した。1341年、ローマで桂冠詩人の栄誉を受けた。古代を輝かしい時代、それ以後を「暗い時代」と考える見方は、ペトラルカに始まるとされる。',
        talk: '14世紀のイタリア。詩人ペトラルカは、修道院の図書館で埃をかぶっていた古代ローマの本を探しまわりました。1345年には、ヴェローナの図書館でキケロが友人にあてた手紙の写本を見つけ、大喜びしたと伝えられています。ペトラルカは、千年以上前の作家に手紙を書くほど古典を愛しました。そして、古代ローマは光の時代、そのあとの時代は暗い時代だ、と考えました。「暗黒の中世」というイメージは、ここから始まったのです。',
