        talk: '中世の西ヨーロッパでは、ギリシア語を読める人はほとんどいませんでした。1397年、ビザンツ帝国の学者クリュソロラスがフィレンツェにやってきて、ギリシア語の授業を始めます。若い学者たちは夢中になりました。やがて大富豪メディチ家のコジモが学者を支援し、フィチーノがプラトンの全作品をラテン語に訳しました。お金をもつ商人が学問と芸術を支える。フィレンツェが「ルネサンスのゆりかご」とよばれたのは、こうした人々のおかげです。',
