        text: '人文主義者は古典の言葉を正確に読む技術をみがいた。1440年、ロレンツォ=ヴァッラは、教皇権の根拠とされた「コンスタンティヌスの寄進状」がその用語や文法から4世紀のものではなく、後世の偽書であることを論証した。',
        talk: '古典をていねいに読む力は、思わぬ武器にもなりました。教皇は長いあいだ、ローマ皇帝コンスタンティヌスが西方の支配権を教皇にゆずったという文書を、自分の権力の根拠にしていました。ところが人文主義者ヴァッラは、この文書のラテン語を調べ、4世紀にはありえない言い回しがたくさんあると指摘します。つまり、のちの時代につくられた偽物だというのです。ことばを正確に読むことが、権威を疑う力になった瞬間でした。',
