        talk: 'ピコ=デラ=ミランドラは、わずか23歳でこう書きました。神はほかの生き物にはそれぞれ決まった性質を与えたが、人間にだけは何も決めずに、自分で自分のかたちを選ぶ自由を与えた。だから人間は、獣のように低くもなれるし、天使のように高くもなれる、と。人間には無限の可能性があるという考えです。同じころフィレンツェでは、レオナルド=ダ=ヴィンチやミケランジェロが、人間の体と心を生き生きと描いていました。',
