        talk: '人文主義は、印刷術の広まりとともにアルプスの北へも伝わりました。その代表がエラスムスです。彼は『愚神礼賛』で、愚かさの女神に語らせる形で、ぜいたくな聖職者や形だけの信仰を笑いものにしました。1516年には、ギリシア語の原文から新約聖書を出版します。翌年、ルターが宗教改革を始めると、人々は「エラスムスが卵を産み、ルターがそれをかえした」と言いました。もっとも、エラスムス本人は教会の分裂を望んでいませんでした。',
