        text: '絶対王政のもとでは、主権は神から授けられた国王にあるとされた（王権神授説）。ジュネーヴ生まれのルソーは1762年の『社会契約論』で、主権は人民全体の一般意志にあり、譲りわたすことも分割することもできないと説いた。',
        talk: 'ルイ14世は「朕は国家なり」と言ったと伝えられます。この言葉が本当かどうかはわかりませんが、当時は王の権力は神から与えられたもの、という考えがふつうでした。これに対し、ルソーは正反対のことを言います。国の最高の力、主権は、人民全体のものだ。それは人民みんなの意志、一般意志としてあらわれ、だれにもゆずりわたせない、と。王さまではなく、わたしたちが主人公だ、という考えが、こうして形になりました。',
