        talk: '国民主権を、はじめて国の土台にすえたのはアメリカでした。独立宣言にはこうあります。政府の正しい権力は、治められる人々の同意から生まれる。合衆国憲法の最初の言葉は、「われら合衆国の人民は」です。「国王陛下は」でも「神は」でもありません。憲法をつくるのは人民だ、とはっきり宣言したのです。ただし、このときの「人民」には、奴隷とされた黒人や先住民、女性は政治の担い手として入っていませんでした。',
