        talk: '「第三身分とは何か。すべてである。これまで何であったか。無であった。何を求めるか。何者かになることを」。1789年の初めに出たシェイエスのパンフレットは、飛ぶように売れました。6月、第三身分の議員たちは、自分たちこそ国民の代表だとして国民議会をつくります。そして8月、人権宣言の第3条は、主権の源は国民にあると定めました。王の国から国民の国へ。フランス革命は、主権のありかをひっくり返したのです。',
