        talk: '国民主権の考えは、200年近くかけて世界に広がりました。日本では、明治の大日本帝国憲法で主権は天皇にあるとされていました。1946年に公布された日本国憲法は、前文で「ここに主権が国民に存することを宣言し」と書いています。同じ年の選挙で、日本の女性ははじめて投票し、39人の女性議員が生まれました。18歳になったら、あなたも主権者として一票を投じます。ルソーやシェイエスが訴えた考えは、あなたの手の中にあるのです。',
