    summary: '社会契約説は、生まれながらの権利（自然権）をもつ個人が、互いに契約を結んで国家をつくったと考える政治思想である。ホッブズ・ロック・ルソーが唱え、王権神授説をくつがえして市民革命と近代民主政治の理論的な支えとなった。',
    exam: ['自然権をもつ個人の契約で国家ができたとする説', 'ホッブズ『リヴァイアサン』、ロック『統治二論』、ルソー『社会契約論』', '王権神授説を否定し、市民革命の理論的根拠に'],
