        talk: 'もし、警察も裁判所も政府もない世界だったら、どうなるでしょう。ホッブズの答えは、とても暗いものでした。人はみな自分の身を守ろうとして争い、「万人の万人に対する闘争」になる。そこでの人生は「孤独で、貧しく、つらく、残酷で、短い」。ホッブズは、内戦で王が処刑されるほどの混乱を目の当たりにしていました。だから人々は、平和のために力を一つの主権者にあずける約束をするのだ、と考えたのです。国家を、神ではなく人々の約束から説明した点が画期的でした。',
