        talk: '「人間は自由なものとして生まれた。しかし、いたるところで鎖につながれている」。ルソーの『社会契約論』は、この有名な一文で始まります。ルソーは、議員を選んで任せるだけでは本当の自由ではない、とまで考えました。人民みんなの意志、一般意志にしたがって、自分たちで法をつくってこそ自由なのだ、と。この本はフランスで禁書にされましたが、のちにフランス革命の指導者ロベスピエールたちの愛読書になりました。',
