        talk: '本の中の考えが、現実の国をつくりかえる。それが市民革命でした。アメリカ独立宣言を書いたジェファソンは、ロックの思想をもとに、人は生命・自由・幸福追求の権利をもち、政府がそれをこわすなら人民は政府を改め廃止できる、と書きました。13年後、フランスの人権宣言も、自然権と国民主権をかかげます。社会契約説は、イギリスで生まれ、アメリカで実行され、フランスで大きく花開いたのです。',
