        talk: '香辛料の物語は、意外と古くから始まります。1世紀のローマでは、インドのコショウが大人気でした。ローマの商人たちは、夏は南西から、冬は北東から吹く季節風に乗ってアラビア海を往復しました。インド南部ではローマの金貨がたくさん見つかっています。408年、ローマを包囲した西ゴートのアラリックは、身代金として金や銀とともに、コショウ3000ポンドを要求したと伝えられます。コショウは、まさに黒い黄金だったのです。',
