        talk: 'ナツメグは、インドネシアのバンダ諸島という、地図でも見つけにくい小さな島々でしかとれませんでした。クローヴも、近くのモルッカ諸島の数島だけです。それがヨーロッパに届くまでには、島の人から中国やムスリムの商人へ、マラッカやインドの港へ、アラビア海をこえてエジプトへ、そしてヴェネツィア商人へと、何度も手をわたります。そのたびに値段は上がりました。ヨーロッパの食卓に届くころには、産地の何十倍、何百倍にもなっていたといわれます。',
