        routes: [{ name: 'ガマの航路', color: '#2e7d32', pts: [[-9.14, 38.71], [-17.0, 15.0], [-25.0, -10.0], [-10.0, -35.0], [18.4, -34.4], [32.0, -26.0], [40.0, -15.0], [39.66, -4.06], [40.1, -3.2], [55.0, 5.0], [75.78, 11.25]] }]
