        talk: '香辛料の大きな利益は、残酷な争いも生みました。オランダ東インド会社は、ナツメグを自分たちだけで売ろうとして、1621年、バンダ諸島に軍を送ります。島の人々の多くが殺されたり、奴隷として連れ去られたりしました。島の人口は1万数千人から千人ほどにまで減ったともいわれます。1667年、オランダはバンダ諸島の小さなラン島を手に入れるかわりに、北アメリカのニューアムステルダムをイギリスにゆずりました。これが今のニューヨークです。',
