        text: '竜門石窟の造営は唐代まで続いた。675年に完成した奉先寺洞の盧舎那仏は高さ約17メートルで、竜門最大の仏像である。造営には則天武后が化粧料から資金を寄進したと伝えられ、その顔は武后がモデルだという伝説もある。',
        talk: '竜門でいちばん有名なのが、奉先寺の盧舎那仏です。高さは約17メートル。ふっくらとした顔に、おだやかなほほえみをたたえています。造営には、皇后だった則天武后が、自分の化粧料から2万貫を寄付したと記録にあります。そのため、この仏の顔は武后の顔をモデルにしたのではないか、という伝説が生まれました。確かな証拠はありません。それでも、のちに中国史上ただ一人の女帝となる武后の面影を、人々はこの仏に重ねてきたのです。',
        place: '竜門石窟 奉先寺洞', lon: 112.47, lat: 34.56, span: 0.3,
