        talk: '竜門石窟は2000年、雲崗石窟は2001年に世界遺産になりました。竜門には約10万体、雲崗には5万体以上の仏像があるといわれます。ところが、近くで見ると首のない仏像がたくさんあります。20世紀の前半、仏の頭が切り取られて売られ、外国の美術館や収集家の手に渡ったのです。近年、その一部が中国に返される動きも出てきました。1500年前の祈りの場は、文化財をどう守るかという今の問題も私たちに問いかけています。',
