        talk: '唐の時代まで、儒学は経典の字句の意味を細かく調べる学問でした。でも、それだけでは「人はどう生きるべきか」「世界はどうできているか」という大きな問いに答えられません。その答えを出していたのは仏教でした。北宋の学者たちは、仏教に負けない、儒学の世界観をつくろうとします。周敦頤は宇宙の始まりを図にし、程頤たちは、ものごとにはそれぞれ「理」、つまりそうあるべき筋道があると説きました。',
