        talk: '朱熹は、北宋の学者たちの考えを一つの大きな体系にまとめました。世界のあらゆるものは、形をつくる「気」と、その筋道である「理」からできている。人の本性も、もともとは理そのものだから善である。だから、一つ一つの物ごとを調べてその理をつかめば、心も正しくなる、というのです。1175年、朱熹は、自分の心をみがけばよいと説く陸九淵と、鵝湖という寺で論争しました。のちの陽明学は、陸九淵の流れをくんでいます。',
