        talk: '1927年、ブリアンはアメリカの人々にメッセージを送りました。アメリカとフランスで、おたがいに戦争をしないと約束しよう、という提案です。実はブリアンには、アメリカをフランスの味方に引きこみたいというねらいもありました。アメリカの国務長官ケロッグは、二国だけの約束では同盟のようになってしまうと考え、「それなら世界中の国で約束しよう」と答えます。こうして、二国の約束は、世界規模の条約へと大きくふくらんでいきました。',
