        talk: '1928年8月27日、パリのフランス外務省の「時計の間」で、15か国の代表が署名しました。その中には日本も入っています。のちに参加国は60をこえました。条文はとても短く、中心は二つだけ。国家の政策の手段として戦争をしない。紛争は平和的な方法で解決する。歴史上はじめて、戦争そのものを悪いことと宣言したのです。ただし、約束を破った国を罰する仕組みはありませんでした。また、自分の国を守るための戦争は別だ、と多くの国が考えていました。',
