        text: '第二次世界大戦後、ニュルンベルク裁判と東京裁判では、不戦条約などを根拠に侵略戦争を計画・実行した「平和に対する罪」が問われた。国際連合憲章は武力の行使と威嚇を原則として禁止し、1946年公布の日本国憲法第9条は「国際紛争を解決する手段としては」戦争を放棄すると定めた。',
