        text: '1954年6月、中国の周恩来首相とインドのネルー首相が会談し、領土・主権の相互尊重、相互不可侵、内政不干渉、平等互恵、平和共存の平和五原則を発表した。同年、インド・パキスタン・セイロン・ビルマ・インドネシアの首相がコロンボで会議を開き、アジア・アフリカ諸国の会議の開催を提案した。',
        talk: '第二次世界大戦後、アジアでは次々に新しい国が独立しました。でも世界は、アメリカとソ連の二つの陣営に分かれて対立しています。どちらかにつかなければならないのでしょうか。1954年、中国の周恩来とインドのネルーが会い、たがいの主権を尊重し、平和に共存しようという平和五原則を発表しました。同じ年、南アジアと東南アジアの5か国の首相がセイロンのコロンボに集まり、アジアとアフリカの国々で大きな会議を開こうと決めます。',
