        talk: '1955年4月18日、ジャワ島の高原の町バンドンに、アジアとアフリカの29か国の代表が集まりました。参加国の人口をあわせると、当時の世界の半分以上になったともいわれます。ほんの十数年前まで、そのほとんどが植民地や従属国でした。主催国インドネシアのスカルノ大統領は、「植民地主義はまだ死んでいない」と訴えました。日本も参加しています。戦争の加害の記憶が残るアジアの国々の前で、日本は平和国家として再出発する姿勢を示そうとしました。',
