        talk: '29か国の立場はばらばらでした。アメリカと同盟を結ぶ国もあれば、共産主義の中国もあります。会議の中で、中国の共産主義を批判する声も上がりました。そのとき周恩来は、「われわれは争うためではなく、団結するために来た。ちがいはそのままに、共通点を求めよう」と語ったと伝えられています。こうしてまとまったのが平和十原則です。人種や国の大小にかかわらず平等であること、内政に干渉しないこと。旧植民地の国々の、心からの願いでした。',
