        talk: 'バンドンに集まった国のうち、アフリカからの参加はまだわずかでした。多くの地域が、植民地のままだったからです。けれども、バンドンの声は大陸に響きました。1957年、ガーナがエンクルマのもとで独立します。そして1960年、アフリカでは一度に17もの国が独立しました。この年は「アフリカの年」とよばれます。国連でも、植民地に独立を与えるべきだという宣言が採択されました。バンドンで灯った火が、アフリカ中に広がったのです。',
