        talk: 'バンドン会議の精神を受けつぎ、1961年、ユーゴスラヴィアの首都ベオグラードで非同盟諸国首脳会議が開かれました。中心になったのは、ユーゴスラヴィアのティトー、エジプトのナセル、インドのネルーです。アメリカの陣営にも、ソ連の陣営にも入らない。自分たちの道は自分たちで決める。こうした国々は「第三世界」とよばれました。今、ニュースで耳にする「グローバル=サウス」という言葉にも、バンドンからの流れが続いています。',
