        talk: '1950年代、世界の大問題といえば、アメリカとソ連の対立、つまり「東西」の問題でした。ところが1959年、イギリスの銀行家フランクスは、もう一つの大問題があると訴えます。豊かな工業国と、貧しい国々との格差です。地図を見ると、豊かな国の多くは北半球の北のほうに、貧しい国の多くはその南に並んでいました。そこで、この問題は「南北問題」とよばれるようになりました。東西の対立と同じくらい、いえそれ以上に大事な問題だ、というのです。',
