        talk: '1973年、中東の産油国が石油の値段を4倍近くに引き上げ、先進国は大混乱におちいりました。石油危機です。資源をもつ国が、その力で世界を動かせることを示したのです。翌年の国連の会議では、自分の国の資源は自分の国が自由に使う権利がある、という新しい経済秩序の宣言が採択されました。ところが今度は、途上国の中でも差が開きます。石油を売って豊かになる国、韓国や台湾のように工業化に成功する国、取り残される国。これが南南問題です。',
